const SB='https://addwjngdezmmnxddulll.supabase.co/rest/v1';
const KEY='<REDACTED_SUPABASE_JWT>';
const H={apikey:KEY,Authorization:'Bearer '+KEY};
const get=async(p)=>this.helpers.httpRequest({method:'GET',url:SB+p,headers:H,json:true});
const comps=await get('/competitors?select=name,type,active&active=eq.true');
const direct=new Set(comps.filter(c=>(c.type||'direct')!=='indirect').map(c=>c.name));
const since=new Date(Date.now()-36*86400000).toISOString().slice(0,10);
const rows=await get('/sov_daily?select=snapshot_date,company,weighted_pct,window_days&window_days=eq.7&snapshot_date=gte.'+since+'&order=snapshot_date.asc&limit=5000');
const byCo={};
for(const r of rows){ if(!direct.has(r.company))continue; (byCo[r.company]=byCo[r.company]||[]).push({day:r.snapshot_date,v:Number(r.weighted_pct)||0}); }
const spikes=[];
for(const [co,arr] of Object.entries(byCo)){
  if(arr.length<10)continue;
  arr.sort((a,b)=>a.day<b.day?-1:1);
  const latest=arr[arr.length-1];
  const hist=arr.slice(0,-1).slice(-28).map(x=>x.v);
  const mean=hist.reduce((s,x)=>s+x,0)/hist.length;
  const sd=Math.sqrt(hist.reduce((s,x)=>s+(x-mean)*(x-mean),0)/hist.length)||0.0001;
  const z=(latest.v-mean)/sd;
  const rel=mean>0?(latest.v-mean)/mean:0;
  const abs=latest.v-mean;
  if((Math.abs(z)>2&&Math.abs(abs)>1.5)||(Math.abs(rel)>0.5&&Math.abs(abs)>2)){
    spikes.push({company:co,day:latest.day,value:latest.v,mean,z,abs,dir:abs>0?'up':'down'});
  }
}
if(!spikes.length)return [];
// attach driving posts (last 48h, by post_weight) for spiking companies
const sinceTs=new Date(Date.now()-48*3600000).toISOString();
const out=[];
for(const s of spikes){
  let drivers=[];
  try{
    const li=await get('/linkedin_posts?select=post_url,text,totalReactions,post_weight&companyName=eq.'+encodeURIComponent(s.company)+'&posted_at=gte.'+encodeURIComponent(sinceTs)+'&order=post_weight.desc.nullslast&limit=3');
    drivers=li.map(p=>({url:p.post_url,text:String(p.text||'').slice(0,140),reactions:p.totalReactions}));
  }catch(e){}
  const arrow=s.dir==='up'?'↑':'↓';
  let text=`:rotating_light: *SOV spike — ${s.company}* ${arrow}\n7-day SOV is *${s.value.toFixed(2)}* vs ~${s.mean.toFixed(2)} trailing-4-week avg (${s.abs>0?'+':''}${s.abs.toFixed(2)} pts, z=${s.z.toFixed(1)}).`;
  if(drivers.length){ text+='\n*Likely drivers (last 48h):*'; for(const d of drivers){ text+=`\n• <${d.url}|${(d.text||'post').replace(/[<>|]/g,'')}> (${d.reactions??'?'} reactions)`; } }
  text+=`\n<https://competitive-intelligence-system.pages.dev|Open the SOV board>`;
  out.push({json:{company:s.company,slackText:text}});
}
return out;
